// --- FILE: src/storage.js ---
const STORAGE_KEY = "bible_outline_studio_v1";

// Returns empty/default user notes database
function createInitialStorage() {
  const books = {};
  const chapters = {};

  BIBLE_BOOKS.forEach((book) => {
    books[book.id] = {
      bookSummary: "",
      myBookTheme: "",
      chapterGroups: [], // Contiguous chapter ranges e.g. { id, title, startChapter, endChapter }
      updatedAt: null
    };

    for (let ch = 1; ch <= book.chapterCount; ch++) {
      const chKey = `${book.id}-${ch}`;
      chapters[chKey] = {
        headingBlocks: [], // Array of heading blocks e.g. { heading, verses, points, notes }
        highlights: [], // Sorted array of highlighted verse numbers e.g. [1, 4, 5]
        verseNotes: [], // Array of verse/range notes e.g. { id, startVerse, endVerse, text, updatedAt }
        annotationsUpdatedAt: null,
        chapterScripture: "", // Cached bible scripture text for the chapter reader
        status: "empty", // 'empty' | 'in-progress' | 'completed'
        takeaway: "",
        updatedAt: null
      };
    }
  });

  return {
    version: 1,
    lastSaved: Date.now(),
    books,
    chapters,
    quizHistory: [],
    bookMastery: {}
  };
}

function loadOutlineStorage() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      const initial = createInitialStorage();
      saveOutlineStorage(initial);
      return initial;
    }
    const data = JSON.parse(raw);
    // Ensure all 66 books & 1,189 chapters exist even if newly added fields
    const defaultData = createInitialStorage();
    if (!data.books) data.books = defaultData.books;
    if (!data.chapters) data.chapters = defaultData.chapters;
    if (!Array.isArray(data.quizHistory)) {
      data.quizHistory = [];
    } else {
      data.quizHistory.forEach((q, idx) => {
        if (!q.id) {
          q.id = `quiz_${q.date || Date.now()}_${idx}`;
        }
      });
    }
    if (!data.bookMastery) data.bookMastery = {};

    BIBLE_BOOKS.forEach((book) => {
      if (!data.books[book.id]) {
        data.books[book.id] = defaultData.books[book.id];
      } else if (!Array.isArray(data.books[book.id].chapterGroups)) {
        // Backward-compatibility: books saved before chapter grouping existed
        data.books[book.id].chapterGroups = [];
      }
      for (let ch = 1; ch <= book.chapterCount; ch++) {
        const chKey = `${book.id}-${ch}`;
        if (!data.chapters[chKey]) {
          data.chapters[chKey] = defaultData.chapters[chKey];
        } else {
          const chData = data.chapters[chKey];
          if (!Array.isArray(chData.headingBlocks)) {
            chData.headingBlocks = [];
          }
          if (!Array.isArray(chData.highlights)) {
            chData.highlights = [];
          }
          if (!Array.isArray(chData.verseNotes)) {
            chData.verseNotes = [];
          }
          // Backward-compatibility: auto-migrate legacy notes/sections if headingBlocks is empty
          if (chData.headingBlocks.length === 0) {
            const legacyHeading = chData.chapterTitle || (Array.isArray(chData.sections) && chData.sections[0]) || "";
            const legacyNotes = chData.notes || "";
            if (legacyHeading.trim() || legacyNotes.trim()) {
              const pts = legacyNotes
                .split("\n")
                .map((l) => l.replace(/^[•\-\*]\s*/, "").trim())
                .filter(Boolean);
              chData.headingBlocks.push({
                heading: legacyHeading.trim() || "Overview",
                verses: "",
                notes: legacyNotes.trim(),
                points: pts
              });
            }
          }
          // Clean up legacy keys
          delete chData.chapterTitle;
          delete chData.sections;
          delete chData.notes;
        }
      }
    });
    return data;
  } catch (err) {
    console.error("Error loading Bible outline storage:", err);
    return createInitialStorage();
  }
}

function saveOutlineStorage(data) {
  try {
    data.lastSaved = Date.now();
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch (err) {
    console.error("Error saving Bible outline storage:", err);
  }
}

let saveTimer = null;
function debouncedSaveOutlineStorage(data, delay = 250) {
  if (saveTimer) clearTimeout(saveTimer);
  saveTimer = setTimeout(() => {
    saveOutlineStorage(data);
  }, delay);
}

