  const { db, doc, setDoc } = await ensureFirebase();
  const quizDocRef = doc(db, "users", user.uid, "quizzes", qId);
  const payload = JSON.parse(JSON.stringify({ ...quizRecord, id: qId }));
  await setDoc(quizDocRef, payload, { merge: true });
